package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;

import org.junit.jupiter.api.Test;

/**
 * Pins the three ordering relations the specialization ladder is required to encode, as opposed to whatever order its
 * entries happen to sit in.
 * <p>
 * The ladder decides whenever cost does not separate two candidates, so its order is not cosmetic: a strategy placed
 * above a faster rival wins every dispatch in which the measured gap fails the displacement test. That is exactly how a
 * reported 2x regression arose — {@code packedFtreeAggregate} sat above the engine's own Janino-compiled aggregate
 * tiers, so it captured queries the compiled kernel ran twice as fast.
 * <ul>
 * <li>The engine's own kernel tiers outrank the packed f-tree rungs, compiled before interpreted, on both the aggregate
 * and the row side.
 * <li>Projection-free wildcard IR stays ahead of its legacy wildcard batch fallbacks.
 * </ul>
 */
class LmdbNativeStrategyPreferenceOrderTest {
	/**
	 * The aggregate side of the reported regression. Compiled parallel heads the tier (it is the arm measured fastest
	 * on the reporter's store), then compiled serial, then the interpreter, and only then the packed f-tree.
	 */
	@Test
	void janinoAggregateTiersOutrankPackedFtreeAggregate() {
		assertRanksAscending(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_PACKED_FTREE_AGGREGATE);
	}

	/** The same relation on the row side: the row kernel tiers outrank the row packed f-tree. */
	@Test
	void rowKernelTiersOutrankPackedFtree() {
		assertRanksAscending(
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_PACKED_FTREE);
	}

	@Test
	void legacyWildcardStrategiesRemainFallbacksBehindIr() {
		List<String> ir = List.of(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_PARALLEL,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_PARALLEL_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED);
		for (String kernel : ir) {
			assertTrue(LmdbNativeStrategyPreference.prefers(kernel,
					LmdbNativeAttemptMetrics.PATH_WILDCARD_PREDICATE_REDUCED));
			assertTrue(LmdbNativeStrategyPreference.prefers(kernel,
					LmdbNativeAttemptMetrics.PATH_WILDCARD_PREDICATE_BATCH));
		}
	}

	@Test
	void wildcardIrKernelsOutrankTheirLegacyFallbacks() {
		assertRanksAscending(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_WILDCARD_PREDICATE_REDUCED);
		assertRanksAscending(
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_WILDCARD_PREDICATE_BATCH);
	}

	@Test
	void everyParallelIrTierHeadsThePreferenceLadder() {
		List<String> compiledParallel = List.of(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_PARALLEL);
		List<String> interpretedParallel = List.of(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_PARALLEL_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_PARALLEL_INTERPRETED);
		List<String> remainingIr = List.of(
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_WILDCARD_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_DISTINCT_INTERPRETED,
				LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED);

		for (String compiled : compiledParallel) {
			for (String interpreted : interpretedParallel) {
				assertTrue(LmdbNativeStrategyPreference.rank(compiled) < LmdbNativeStrategyPreference.rank(interpreted),
						compiled + " must outrank interpreted parallel " + interpreted);
			}
		}
		for (String interpreted : interpretedParallel) {
			for (String serial : remainingIr) {
				assertTrue(LmdbNativeStrategyPreference.rank(interpreted) < LmdbNativeStrategyPreference.rank(serial),
						interpreted + " must outrank serial IR " + serial);
			}
		}
		int lastIr = remainingIr.stream()
				.mapToInt(LmdbNativeStrategyPreference::rank)
				.max()
				.orElseThrow();
		assertTrue(lastIr < LmdbNativeStrategyPreference.rank(LmdbNativeAttemptMetrics.PATH_EXISTS_INTERSECTION));
	}

	private static void assertRanksAscending(String... tags) {
		for (int i = 1; i < tags.length; i++) {
			int higher = LmdbNativeStrategyPreference.rank(tags[i - 1]);
			int lower = LmdbNativeStrategyPreference.rank(tags[i]);
			assertTrue(higher < lower,
					tags[i - 1] + " (rank " + higher + ") must outrank " + tags[i] + " (rank " + lower + ")");
		}
	}
}
